import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Tentacle - Telemetry","description":"","frontmatter":{"title":"CDS Tentacle - Telemetry","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","Telemetry","Storage Metrics","Ceph Stretch Mode","Ceph Monitoring"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_Telemetry.md","filePath":"posts/2024/CDS_Tentacle_-_Telemetry.md","lastUpdated":1780459816000}'),o={name:"posts/2024/CDS_Tentacle_-_Telemetry.md"};function n(s,l,a,p,g,u){return e(),r("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 存储系统 Telemetry 功能讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Ceph 团队成员，包括研发人员、测试人员、用户代表等</p><p><strong>会议内容</strong>：</p><p><strong>一、Stretch 模式指标收集</strong></p><ul><li><strong>讨论背景</strong>： 为了解 Stretch 模式的使用情况，需要收集相关指标。</li><li><strong>解决方案</strong>： <ul><li>通过 OSD 映射中的标志位收集 Stretch 模式状态信息。</li><li>使用 Telemetry 模块收集数据，可追溯到几代版本。</li><li>讨论了 Stretch 模式和 Stretch 集群的差异，以及进入 Stretch 模式所需的准备工作和配置。</li></ul></li><li><strong>行动计划</strong>： <ul><li>Junior 将研究是否需要收集其他相关信息。</li><li>在 Stretch 集群上进行测试，验证指标收集是否正确。</li></ul></li></ul><p><strong>二、其他指标收集</strong></p><ul><li><strong>讨论背景</strong>： 讨论了其他需要收集的指标，例如： <ul><li>用户对其他功能的使用情况。</li><li>其他未收集的指标，例如 RBD、RGW 和 FFS 的应用层指标。</li><li>RGW 多站点集群的统计信息。</li><li>蓝存储分配器性能指标。</li></ul></li><li><strong>解决方案</strong>： <ul><li>讨论了如何收集和分析这些指标，例如： <ul><li>使用 Grafana 进行可视化。</li><li>开发新的 Telemetry 模块。</li><li>从性能计数器中推断信息。</li></ul></li></ul></li><li><strong>行动计划</strong>： <ul><li>将讨论结果提交给用户开发会议，进一步讨论和确定具体的指标收集方案。</li></ul></li></ul><p><strong>三、Telemetry 分析报告</strong></p><ul><li><strong>讨论背景</strong>： 讨论了如何向用户提供 Telemetry 分析报告，帮助用户了解其部署状态和潜在问题。</li><li><strong>解决方案</strong>： <ul><li>讨论了两种方案： <ul><li>在 Telemetry 网页或 Grafana 上提供更个性化的分析报告。</li><li>开发一个 Telemetry 命令，生成分析报告。</li></ul></li></ul></li><li><strong>行动计划</strong>： <ul><li>研究现有的 AI 工具，例如 SE Report，以获取灵感。</li><li>研究如何将敏感信息匿名化。</li><li>讨论如何将分析报告集成到现有的工具中。</li></ul></li></ul><p><strong>四、其他事项</strong></p><ul><li>讨论了如何改进升级路径的数据库，以便更好地了解不同版本之间的兼容性。</li><li>讨论了如何使用 Telemetry 数据来评估版本稳定性，并帮助用户做出升级决策。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了 Ceph 存储系统 Telemetry 功能的多个方面，包括指标收集、分析报告和用户体验等。会议达成了多项共识，并制定了后续行动计划。</p>',15)])])}const T=t(o,[["render",n]]);export{c as __pageData,T as default};
